css:
/* The "Find a location" band: a map, two facet filters and a scrolling row of
   location cards. The pills and the cards are coded widgets because the
   platform filter behaviour matches a card's facets from its own data-
   attributes, and no block prop emits those; the behaviour itself is declared
   on the section, so the filtering is not scripted. */

/* The handoff gives this band 120px of air top and bottom. */
[data-bz-section="location-rail"] > .bz-section { padding-block: 120px }
[data-bz-section="location-rail"] .bz-block { padding-block: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-head-col"] .bz-block + .bz-block { padding-block-start: 18px }
[data-bz-section="location-rail"] h2 { font-size: 38px; margin: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-body"] .bz-text { max-width: 640px }
[data-bz-section="location-rail"] [data-bz-node="lr-body"] p { font-size: 16px; line-height: 1.6; color: var(--body-text); margin: 0 }
[data-bz-section="location-rail"] [data-bz-node="lr-head"] { margin-bottom: 40px }

[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-map {
  width: 100%; aspect-ratio: auto; min-height: 460px;
  background: var(--paper); border: 1px solid var(--line); margin: 0;
  border-radius: 0;
}
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-loclist { display: none }
[data-bz-section="location-rail"] [data-bz-node="lr-map"] .bz-widget__empty { display: none }
[data-bz-section="location-rail"] [data-bz-node="lr-map-row"] { margin-bottom: 44px }

[data-bz-section="location-rail"] [data-bz-node="lr-brands"] { margin-bottom: 18px }
[data-bz-section="location-rail"] [data-bz-node="lr-perks"] { margin-bottom: 0 }

[data-bz-section="location-rail"] [data-bz-node="lr-nav-row"] { margin-block: 44px 20px }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-btns { margin-block: 0; justify-content: flex-end; gap: 8px }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-btn {
  width: 38px; height: 38px; min-height: 0; padding: 0;
  border: 1px solid var(--line); background: var(--card); color: var(--ink);
  font-family: var(--font-body); font-weight: 400; font-size: 15px;
}
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-btn:hover { border-color: var(--muted) }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] { display: flex; justify-content: flex-end; align-items: center; gap: 8px }
[data-bz-section="location-rail"] [data-bz-node="lr-nav"] .bz-block { padding-block: 0 }
@media (max-width: 640px) {
  /* The handoff keeps the rail arrows on a phone. */
  [data-bz-section="location-rail"] .ss-filter__l { flex-basis: auto; padding-top: 0 }
}

js:
/* Arrow scrolling for the location rail.
 *
 * The filtering itself is the platform `filter` behaviour declared on the
 * section — nothing here touches it. The rail's own horizontal scroll is a
 * plain overflow container, correct with no script at all; these two buttons
 * only page it, and they are real links until this runs.
 */
(function () {
  document.querySelectorAll('[data-bz-section="location-rail"]').forEach(function (band) {
    var track = band.querySelector('.ss-locrail__track');
    if (!track) return;
    function page(dir) {
      var card = track.querySelector('.ss-loc:not([hidden])');
      var step = card ? card.offsetWidth + 20 : track.clientWidth;
      track.scrollBy({ left: dir * step, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    }
    ['lr-prev', 'lr-next'].forEach(function (id, i) {
      var host = band.querySelector('[data-bz-node="' + id + '"]');
      var control = host && host.querySelector('a, button');
      if (!control) return;
      control.addEventListener('click', function (event) {
        event.preventDefault();
        page(i === 0 ? -1 : 1);
      });
    });
  });
})();
